#!/usr/bin/env node
'use strict';

// The actual tunnel-client owns YAML parsing.  This wrapper never accepts an
// owner profile: it asks that client to materialize the one permitted stdio
// binding, then doctors the exact generated bytes by --profile-file.
const crypto = require('node:crypto');
const fs = require('node:fs');
const path = require('node:path');
const { execFileSync } = require('node:child_process');
const { loadContract, buildRestrictedLaunch, validateLocalReadiness } = require('./m3-remote-contract.cjs');

const SEALED_PROFILE = 'm3-sealed-profile.yaml';
function fail(message) { throw new Error(`M3 owner preflight refused: ${message}`); }
function sha(file) { return crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex'); }
function absolute(value, name) { if (typeof value !== 'string' || !path.win32.isAbsolute(value)) fail(`${name} must be an absolute Windows path`); return path.resolve(value); }
function tunnelId(value) { if (typeof value !== 'string' || !/^tunnel_[0-9a-f]{32}$/.test(value)) fail('tunnel-id is invalid'); return value; }
function parseArgs(argv) { if (argv.length !== 4 || argv[0] !== '--tunnel-client' || argv[2] !== '--tunnel-id') fail('usage: m3-owner-preflight.cjs --tunnel-client <absolute .exe> --tunnel-id <owner tunnel id>'); return { tunnelClient: absolute(argv[1], 'tunnel-client'), tunnelId: tunnelId(argv[3]) }; }
function tunnelEnv(env, credential) {
  const result = { ...env };
  for (const name of Object.keys(result)) if (name === 'OPENAI_API_KEY' || name.startsWith('CONTROL_PLANE_') || name.startsWith('MCP_') || name.startsWith('TUNNEL_CLIENT_')) delete result[name];
  // Keep only the owner-provided runtime key; it is not launch authority.
  if (typeof env[credential] === 'string') result[credential] = env[credential];
  return result;
}
function publish(runtimeRoot, value) { fs.mkdirSync(runtimeRoot, { recursive: true }); fs.writeFileSync(path.join(runtimeRoot, 'm3-tunnel-state.json'), `${JSON.stringify(value)}\n`, 'utf8'); }
function prepare({ options, env = process.env, worktree, execFile = execFileSync, runtimeRoot } = {}) {
  const contract = loadContract(); const ready = validateLocalReadiness({ contract, worktree, env });
  if (!options || !fs.existsSync(options.tunnelClient)) fail('tunnel-client executable was not found');
  if (typeof env[contract.credentialEnvironment] !== 'string' || env[contract.credentialEnvironment].trim() === '') fail(`${contract.credentialEnvironment} is required only for this owner process`);
  const launch = buildRestrictedLaunch({ contract, worktree }); const outputRoot = runtimeRoot || contract.runtimeRoot; const profile = path.join(outputRoot, SEALED_PROFILE); const safeEnv = tunnelEnv(env, contract.credentialEnvironment);
  try {
    execFile(options.tunnelClient, ['init', '--sample', 'sample_mcp_stdio_local', '--profile', path.basename(profile, '.yaml'), '--profile-dir', outputRoot, '--tunnel-id', options.tunnelId, '--control-plane-api-key-ref', `env:${contract.credentialEnvironment}`, '--mcp-command', launch.command.replaceAll('\\', '/'), '--health-listen-addr', '127.0.0.1:0', '--force'], { cwd: launch.cwd, env: safeEnv, windowsHide: true, stdio: 'ignore', timeout: 60_000 });
    if (!fs.existsSync(profile)) fail('tunnel-client did not create the sealed profile');
    const profileSha = sha(profile);
    execFile(options.tunnelClient, ['doctor', '--profile-file', profile, '--explain'], { cwd: launch.cwd, env: safeEnv, windowsHide: true, stdio: 'ignore', timeout: 60_000 });
    if (sha(profile) !== profileSha) fail('sealed profile changed during doctor');
    const evidence = { schema_version: 2, state: 'DOCTOR_PASSED', checkout_head: ready.checkout_head, profile: contract.tunnelProfile, artifact: profile, profile_sha256: profileSha, launcher_sha256: sha(launch.command), policy_sha256: sha(launch.policy_path), tunnel_client: options.tunnelClient, generated_at: new Date().toISOString() };
    publish(outputRoot, evidence); return evidence;
  } catch (error) { publish(outputRoot, { schema_version: 2, state: 'DOCTOR_FAILED', checkout_head: ready.checkout_head, profile: contract.tunnelProfile, generated_at: new Date().toISOString() }); throw error; }
}
function main(argv = process.argv.slice(2), env = process.env, worktree) { return prepare({ options: parseArgs(argv), env, worktree }); }
if (require.main === module) { try { process.stdout.write(`${JSON.stringify(main(), null, 2)}\n`); } catch (error) { process.stderr.write(`${error.message}\n`); process.exitCode = 2; } }
module.exports = { SEALED_PROFILE, parseArgs, tunnelEnv, prepare, main };
